        "en": "A customer returned to the studio with a complaint: an order had arrived late, and its design did not match what she had approved. Nina offered an apology, but the customer asked a harder question: “How will you stop this from happening again?”",
        "zh": "一位顧客帶著客訴回到工作室：訂單晚到，設計也和她批准的版本不同。Nina 先道歉，但顧客問了更難回答的問題：「你們要怎麼防止再次發生？」"
