        "zh": "工作室給 Nina 一份較長的合約，也讓她有機會帶領小專案。「我以為成功就是證明所有人都錯了，」她坦言，「現在我覺得，是和別人一起建立值得投入的東西。」她第一次感到動力穩定，而不是出於急迫感。"
