        "en": "The professor said, “Technology can help us study the universe, but it cannot replace academic honesty.” Kai left the missing value blank, then wrote exactly why it was absent. The emptiness on the graph was information too.",
        "zh": "教授說：「科技能幫助我們研究宇宙，但無法取代學術誠實。」Kai 保留空白，並清楚寫下缺值原因。圖上的空白本身也是資訊。"
