        "en": "That night, the station’s receiver showed an unusual signal. A technician raised an alert and asked Kai not to announce a new phenomenon before an investigation. The team monitored the same frequency for another hour. Every time the portable battery was moved, the signal changed.",
        "zh": "那天晚上，觀測站的接收器出現異常訊號。技師發出警示，請 Kai 在調查前別急著宣布新現象。團隊持續監測同一頻率一小時。每當可攜式電池被移動，訊號就會改變。"
