        "en": "Kai revised the report one final time. He acknowledged the limitation of the telescope data and included evidence from the repeated laboratory test. The conclusion was less exciting than he had first hoped, but it was reliable. His professor approved the revision for publication.",
        "zh": "Kai 最後一次修改報告。他承認望遠鏡資料的限制，也納入實驗室重複測試的證據。結論沒有他起初想像的刺激，卻可靠。教授批准修訂版送交出版。"
