        "zh": "家人願意合作，但有一個條件：私人信件必須維持私密。他們希望大眾珍惜旅人的作品，而不是把作品裡每個人都當成娛樂角色。Iris 向他們保證，展示任何一頁之前都會先徵得許可。"
