        "en": "The injured dancer came to watch from the audience seats. She had written the note herself. “The show should go on,” she said, “but please ask what everyone can safely do first.” Mei realized that the next rehearsal would require more than music.",
        "zh": "受傷舞者坐在觀眾席來看排練。那張紙條是她自己寫的。「演出應該繼續，」她說，「但請先問問每個人能安全做到什麼。」Mei 意識到下次排練需要處理的不只是音樂。"
