        "en": "At the celebration, the audience expected a famous solo. Instead, they saw a company moving as one. The new performance told a simple story about helping someone stand after a fall. At first the room was quiet. Then applause rose from the back row and reached the stage like a wave.",
        "zh": "節慶當天，觀眾原本期待一段知名獨舞，看到的卻是整團合作的新演出。作品講述人跌倒後，別人如何幫助他重新站起。觀眾起初很安靜，隨後掌聲從後排湧起，如浪潮般傳到舞台。"
