        "en": "The drone found that the final bridge was still standing. It also found a handwritten sign: “People inside, no medicine.” The third light came from a small house that had been left off the new map. The team now had a destination, not yet a safe path.",
        "zh": "無人機發現最後一座橋仍然完好，也拍到一塊手寫牌子：「屋內有人，沒有藥。」第三盞燈來自一棟新版地圖漏標的小房子。救援隊終於知道目標在哪裡，但安全路線仍待確認。"
