    "title": "A Reservation for Nobody",
    "zh": "不存在的訂房",
    "blurb": "暴雨夜，已客滿的旅館多出一筆訂房；登記姓名竟是三年前失蹤的人。",
    "scene": "night",
    "words": [
      "reservation",
      "registration",
      "vacancy",
      "overnight",
      "reception",
      "suspicious",
      "signature",
      "witness"
    ],
    "pages": [
      {
        "en": "At the Riverside Hotel, every room was booked for the conference. Nora worked at reception, where she checked each guest’s reservation and registration form. At 11:40 p.m., the computer showed a vacancy in Room 406—although its key had been missing for years. An overnight booking appeared under the name Daniel Reed. Nora recognized the signature: Daniel had disappeared three years earlier.",
        "zh": "河畔旅館因會議而客滿。Nora 在櫃台核對每位房客的訂房與登記表。晚上十一點四十分，電腦卻顯示 406 房有空房——明明那把房鑰匙已失蹤多年。一筆過夜訂房的姓名是 Daniel Reed。Nora 認得那個簽名：Daniel 三年前就失蹤了。"
      },
      {
        "en": "She called the night manager. He said it was probably a system error and told her to delete the record. But Nora noticed a suspicious detail: the booking had been entered from the guest computer in the empty lounge, not from the hotel desk. Someone had come into the building to leave the message.",
        "zh": "她打電話給夜班經理。經理認為大概是系統錯誤，要她刪除紀錄。但 Nora 注意到一個可疑細節：這筆訂房是從空蕩交誼廳裡的訪客電腦輸入，不是櫃台。有人走進旅館，刻意留下這段訊息。"
      },
      {
        "en": "Before Nora could check the security video, a woman entered, soaked by the rain. “I am here as a witness,” she said. “Three years ago, I saw Daniel leave this hotel. Tonight I received a message asking me to return.” The woman placed an old room key on the counter. Its metal tag read 406.",
        "zh": "Nora 還來不及查看監視影像，一名被雨淋得全身濕透的女人走了進來。「我是以目擊者身分來的，」她說，「三年前我看見 Daniel 離開這間旅館。今晚有人傳訊叫我回來。」女人把一把舊鑰匙放上櫃台。金屬牌上寫著 406。"
      }
    ],
