    "pages": [
      {
        "en": "A detective came to the hotel and asked the woman, Eva, to describe what she had seen. She showed him a photograph of Daniel beside his twin brother, Leo. The brothers looked almost identical. “Daniel wore a blue coat that night,” Eva said. “How did you distinguish him from Leo?” the detective asked. Eva pointed to a distinct mark near Daniel’s eye.",
        "zh": "一名偵探來到旅館，請女人 Eva 描述當年看到的事。她拿出一張 Daniel 和雙胞胎兄弟 Leo 的合照。兩人幾乎一模一樣。「Daniel 那晚穿藍色外套，」Eva 說。「妳怎麼分辨他和 Leo？」偵探問。Eva 指向 Daniel 眼睛旁一個明顯的小記號。"
      },
      {
        "en": "Nora checked the old video. The man leaving the hotel wore a hat pulled low, almost like a disguise. But he stopped to look at his reflection in the door. The small mark was missing. “You did not see Daniel leave,” Nora told Eva. “You saw Leo.” Eva went pale. She had told her story so often that she had begun to believe it.",
        "zh": "Nora 查看舊影像。走出旅館的男人把帽子壓得很低，幾乎像在偽裝。但他停下來看玻璃門裡的倒影時，眼旁沒有那個記號。「妳看到離開的人不是 Daniel，」Nora 告訴 Eva，「是 Leo。」Eva 臉色發白。她講述那個版本太多次，連自己都開始相信。"
      },
      {
        "en": "The detective did not call Eva a liar. A mistaken witness was not necessarily guilty of anything. Yet he could not clear Leo merely because the brothers looked alike. There was still no proof of Daniel’s innocence or Leo’s guilt. Then the guest computer printed a second reservation: “Ask Leo why he kept the key.”",
        "zh": "偵探沒有把 Eva 稱作說謊者。認錯人的目擊者，不一定犯了什麼罪。但他也不能只因兄弟長得像，就直接替 Leo 開脫。目前沒有證據證明 Daniel 無辜，也無法判定 Leo 有罪。這時訪客電腦印出了第二張訂房單：「問 Leo 為什麼留下鑰匙。」"
      }
    ],
