        "en": "The manager wanted the minimum cost and maximum publicity before the deadline. He pointed to a narrow profit margin and said the company could not afford extra work. Ren asked why safety had been treated as an optional decoration. The manager called the path a decoration and said inflation could increase the bill. Ren replied that a percentage on paper did not measure the danger to children.",
