        "zh": "Ren 承認自己的第一份報告也忽略了樓梯。「我當時只想替工程辯護，沒有仔細聽人說話，」他說。批評令人不舒服，卻有建設性。團隊調整計畫，讓行人、騎車者與提行李的人都能通行。 團隊得調整時程、公平分工。Ren 說，有建設性的批評，只有在團隊願意行動時才有意義。"
