        "en": "Mara found a cabinet behind the abandoned greenhouse. Inside were jars of seeds and a note: “Keep them separate.” The old nursery had been part of a biological experiment, but the project had ended without a public report.",
        "zh": "Mara 在廢棄溫室後方找到一個櫃子，裡面是種子罐和一張紙條：「分開保存。」舊苗圃曾參與一項生物實驗，但計畫結束後沒有公開報告。"
