        "zh": "研究員告訴 Mara，每罐種子都來自不同山谷。實驗植物單獨生長時表現良好，但沒人知道它們一起擴散會發生什麼。「一罐裡的好結果，不代表在任何地方都好，」她說。 研究員警告，種子罐上的微生物可能混淆結果。她不願為了拍下戲劇性的照片，就讓村莊承擔潛在風險。"
