        "en": "The flowers had formed a line beside the water channel. Mara followed their formation toward the village. Water circulated through old pipes under the greenhouse, and the plants had reached every wet opening. Fresh water would circulate through the channel, but its circulation depended on a continual flow from the old pump.",
        "zh": "花朵沿著水渠排成一線。Mara 順著排列一路走向村子。水在溫室底下的舊管線循環，植物也沿著每個潮濕的出口生長。 清水會沿水渠循環，但水流能否持續循環，取決於舊水泵是否不斷供水。"
