        "en": "A storm bulletin appeared on the city website at six. The new technological system sent alerts to phones, but many elderly residents did not use them. Mei, a volunteer, noticed that the warning listed households by internet address, not by physical street. The initial bulletin had been distributed online, but its distribution had never been checked against actual streets.",
        "zh": "傍晚六點，城市網站出現暴雨公告。新科技系統會把警報送到手機，但很多長者不用。志工 Mei 發現警示名單是依網路位址整理，不是實際街道。 最初的公告只在線上發布，卻從未核對傳送範圍是否涵蓋真實街道。"
