    "series": "第十六部 · 暴雨前的四小時（3 章）",
    "title": "A Map Made for People",
    "zh": "為人而畫的地圖",
    "blurb": "暴雨過後，Mei 交出一份手工地圖，要求市府改變警報方式。",
    "scene": "meeting",
