        "zh": "教練提醒她維持穩定配速。「妳不是在跟攝影機比賽，」他說。Lian 運動能力不錯，卻從未參加這麼大型的比賽。她想完賽，即使沒有人注意。 領先者誇耀想創下雄心勃勃的紀錄。Lian 卻專注道路；對她來說，集中注意力比新聞標題重要。"
