        "en": "On what would have been her parents’ wedding anniversary, Sara counted five places at the restaurant table. Her mother said the extra seat was a mistake. Yet the reservation had been made with the name of Sara’s father, who had been absent since the divorce ten years earlier. Sara felt both anger and a curiosity she did not want to admit.",
        "zh": "在原本應是父母結婚周年的日子，Sara 數到餐廳桌上有五個座位。母親說多出的一席是錯誤。但訂位使用的是 Sara 父親的名字；他在十年前離婚後就缺席了。Sara 既生氣，也有一份不願承認的好奇。"
