        "zh": "盒裡有 Sara 小時候寫的信，沒有一封寄到父親手中。母親當時留下信件，是害怕再起爭吵。Sara 的兩種記憶痛苦地撞在一起：她以為父親忽視自己，父親卻以為她不願聯絡。"
