        "en": "At home, Sara read the letters. Some were full of childish mischief; one complained that her father never remembered her favorite recipe. The last letter surprised her: it asked him not to come to school because she was ashamed of his public arguments with her mother.",
        "zh": "回家後 Sara 讀起信。有些滿是孩子的惡作劇；有一封抱怨父親從不記得她最愛的食譜。最後一封讓她吃驚：她曾請父親不要到學校，因為她為父母公開爭吵感到羞愧。"
