    "pages": [
      {
        "en": "At a mountain observatory, physicist Dr. Ren studied images of a small object near the moon. Her prediction showed a shadow moving in the wrong direction. A camera behind the observation window recorded the same movement three nights in a row, but her colleagues suspected a faulty sensor rather than new physics.",
        "zh": "山上天文台裡，物理學家 Ren 博士研究月亮附近一個小物體的影像。她的預測顯示陰影會朝錯誤方向移動。觀測窗後的攝影機連續三晚錄到相同變化，同事則懷疑是感測器故障，而非新物理現象。"
      },
      {
        "en": "The night cleaner, Bo, had taken photography classes. He had watched the shadow through a window while polishing the floor. “It moves only when the city lights blink,” he said. Ren did not dismiss him because he lacked a diploma. She asked him to show her where he stood.",
        "zh": "夜班清潔員 Bo 上過攝影課。他擦地時透過窗戶看陰影。「只有城市燈光閃爍時它才會動，」他說。Ren 沒因他沒有文憑就否定他的說法，而是請他指出觀看位置。"
      },
      {
        "en": "From the window, Ren saw the answer: a vast advertisement screen on a distant hill reflected against the glass. The apparent moon shadow belonged to the city. But when the screen went dark, a second, smaller shadow remained.",
        "zh": "從那扇窗，Ren 看到了答案：遠方山丘的大型廣告螢幕反射在玻璃上。看似月亮的陰影其實來自城市。但螢幕暗下後，還有第二道較小的陰影留著。"
      }
    ],
