        "en": "Another laboratory published a report first. Its lead researcher claimed absolute certainty that the object was a satellite fragment. Ren felt a flash of jealousy, but the report used only part of the available data. Her own team had located the object; the other team had found its original launch number.",
        "zh": "另一間實驗室搶先發表報告，主研究員宣稱絕對確定物體是衛星碎片。Ren 心頭閃過嫉妒，但報告只用了部分資料。她的團隊定位物體；另一團隊找到原始發射編號。"
