        "en": "The final report explained the shadow without claiming a revolutionary change in physics. Ren added a section about the optical reflection and an acknowledgment for Bo’s observation. Bo read it and said he did not need to become a famous scientist. He wanted a window that did not reflect the billboard.",
        "zh": "最終報告解釋了陰影，沒有宣稱物理學發生革命性變化。Ren 增加一節描述光學反射，也在致謝中記下 Bo 的觀察。Bo 讀完說他不需要成為知名科學家；他只想要一扇不會反射廣告螢幕的窗。"
