        "en": "At the first stop, an elderly woman showed Arun a register from the old post office. It recorded that the missing parcel had been delivered on time. At the second, a former clerk produced a receipt bearing Arun’s signature. He had signed it in haste and later forgotten. The colleague had tried to correct the record, but nobody listened.",
        "zh": "第一站，一位老太太讓 Arun 看舊郵局登記簿，上面記錄遺失包裹其實準時送達。第二站，一名前職員拿出收據，上面有 Arun 的簽名。他當年匆忙簽下，之後忘得一乾二淨。同事試過更正紀錄，卻沒人肯聽。"
