        "en": "A former minister claimed the old constitution had given the commander authority to remove families. Yet the copy in the ministry was missing one article. Nia could not determine whether the loss was accidental or a cunning attempt to hide a violation. She asked a legal scholar to examine both versions.",
        "zh": "前部長聲稱舊憲法賦予指揮官驅離家庭的權力，但部會保存的版本少了一條。Nia 無法斷定是意外遺失，還是狡猾地掩蓋違法行為，於是請法律學者比對兩個版本。"
