        "zh": "報告中的殘酷讓 Nia 灰心。她原以為會讀到征服與勝利，卻看到求生的故事。孫子請她翻譯祖母的話，不要把悲傷寫成娛樂。Nia 第一次明白一個草率形容詞的代價。"
