        "zh": "一名百萬富翁提議捐出大筆錢，條件是 Mei 撤回說法。他說名畫家的名字早成了奢侈品牌，改標籤會影響銷售。Mei 勃然大怒，館長卻要她耐心：他們需要證據，不是復仇。"
